<?php
namespace App\Http\Controllers;
use Illuminate\Http\Request;use Illuminate\Support\Facades\DB;
use App\Models\CriterioEvaluacion;use App\Models\Calificacion;
class EvaluacionController extends Controller {
 public function index(){ $cargas=DB::table('cargas_lectivas')->join('unidades_didacticas','unidades_didacticas.id','=','cargas_lectivas.unidad_didactica_id')->select('cargas_lectivas.id','unidades_didacticas.nombre')->get();return view('evaluaciones.index',compact('cargas')); }
 public function criterios(Request $r){$d=$r->validate(['carga_lectiva_id'=>'required|exists:cargas_lectivas,id']);$criterios=CriterioEvaluacion::where('carga_lectiva_id',$d['carga_lectiva_id'])->orderBy('orden')->get();$peso=$criterios->sum('porcentaje');return view('evaluaciones.criterios',compact('criterios','peso')+['carga'=>$d['carga_lectiva_id']]);}
 public function guardarCriterio(Request $r){$d=$r->validate(['carga_lectiva_id'=>'required|exists:cargas_lectivas,id','tipo'=>'required|string|max:40','nombre'=>'required|string|max:120','indicador'=>'nullable|string|max:180','porcentaje'=>'required|numeric|min:0|max:100','orden'=>'required|integer|min:1']);$actual= CriterioEvaluacion::where('carga_lectiva_id',$d['carga_lectiva_id'])->sum('porcentaje');if($actual+$d['porcentaje']>100) return back()->withErrors(['porcentaje'=>'La suma de ponderaciones no puede superar 100%.'])->withInput();CriterioEvaluacion::create($d+['es_calificable'=>true,'estado'=>true]);return back()->with('ok','Criterio agregado.');}
 public function matriz(Request $r){$d=$r->validate(['carga_lectiva_id'=>'required|exists:cargas_lectivas,id']);$criterios=CriterioEvaluacion::where('carga_lectiva_id',$d['carga_lectiva_id'])->where('es_calificable',1)->orderBy('orden')->get();$alumnos=DB::table('matriculas')->join('estudiantes','estudiantes.id','=','matriculas.estudiante_id')->where('matriculas.carga_lectiva_id',$d['carga_lectiva_id'])->where('matriculas.estado','activo')->select('matriculas.id as matricula_id','estudiantes.id as estudiante_id','estudiantes.codigo_estudiante','estudiantes.apellidos','estudiantes.nombres')->orderBy('estudiantes.apellidos')->get();$notas=Calificacion::whereIn('matricula_id',$alumnos->pluck('matricula_id'))->get()->keyBy(fn($n)=>$n->matricula_id.'_'.$n->criterio_evaluacion_id);return view('evaluaciones.matriz',compact('criterios','alumnos','notas')+['carga'=>$d['carga_lectiva_id']]);}
 public function guardarNotas(Request $r){$d=$r->validate(['notas'=>'required|array','notas.*'=>'nullable|numeric|between:0,20','carga_lectiva_id'=>'required|integer']);DB::transaction(function()use($d){foreach($d['notas'] as $key=>$nota){[$matricula,$criterio]=array_map('intval',explode('_',$key));$m=DB::table('matriculas')->where('id',$matricula)->first();if(!$m)continue;$c=CriterioEvaluacion::find($criterio);if(!$c||$c->carga_lectiva_id!=$d['carga_lectiva_id'])continue;Calificacion::updateOrCreate(['matricula_id'=>$matricula,'criterio_evaluacion_id'=>$criterio],['nota'=>$nota,'docente_id'=>auth()->user()->docente->id??1,'estudiante_id'=>$m->estudiante_id,'fecha_registro'=>now()]);}});return back()->with('ok','Calificaciones guardadas.');}
 public function promedios($carga){$rows=DB::table('matriculas')->join('estudiantes','estudiantes.id','=','matriculas.estudiante_id')->leftJoin('calificaciones','calificaciones.matricula_id','=','matriculas.id')->leftJoin('criterios_evaluacion','criterios_evaluacion.id','=','calificaciones.criterio_evaluacion_id')->where('matriculas.carga_lectiva_id',$carga)->select('matriculas.id','estudiantes.codigo_estudiante','estudiantes.apellidos','estudiantes.nombres',DB::raw('SUM(calificaciones.nota * criterios_evaluacion.porcentaje / 100) as promedio'))->groupBy('matriculas.id','estudiantes.codigo_estudiante','estudiantes.apellidos','estudiantes.nombres')->paginate(30);return view('evaluaciones.promedios',compact('rows','carga'));}
}
